create or replace function public.retreat_event_slug(value text) returns text language sql immutable set search_path='' as $$ select coalesce(nullif(trim(both '-' from regexp_replace(lower(value),'[^a-z0-9]+','-','g')),''),'event') $$;
create or replace function public.create_retreat_event(p_title text,p_product_id uuid,p_start_date date,p_end_date date,p_capacity smallint,p_status public.event_status,p_description text) returns uuid language plpgsql security definer set search_path='' as $$ declare eid uuid; base text; candidate text; n integer:=1; begin if not (select retreat_private.is_retreat_admin()) then raise exception 'Not authorized'; end if; if p_capacity<=0 or p_end_date<p_start_date then raise exception 'Invalid event details'; end if; perform pg_catalog.pg_advisory_xact_lock(735391); base:=public.retreat_event_slug(p_title); candidate:=base; while exists(select 1 from public.retreat_events where slug=candidate) loop n:=n+1; candidate:=base||'-'||n; end loop; if p_status='published' and exists(select 1 from public.retreat_events e where e.status='published' and e.start_date<=p_end_date and e.end_date>=p_start_date) then raise exception 'These dates overlap another published event.'; end if; if p_status='published' and exists(select 1 from public.retreat_bookings b where b.retreat_event_id is null and b.booking_status in('confirmed','completed') and b.start_date<=p_end_date and coalesce(b.end_date,b.start_date)>=p_start_date) then raise exception 'These dates are already occupied by a private retreat.'; end if; insert into public.retreat_events(title,slug,retreat_product_id,retreat_format,start_date,end_date,capacity,available_places,status,description) values(p_title,candidate,p_product_id,'join_a_group',p_start_date,p_end_date,p_capacity,p_capacity,p_status,nullif(p_description,'')) returning id into eid; return eid; end; $$;
revoke all on function public.retreat_event_slug(text) from public,anon,authenticated;
